  1→//! Gap checker for requirement evaluation.
  2→//!
  3→//! The `GapChecker` evaluates whether system-level requirements are met,
  4→//! caching results within a run to avoid redundant command executions.
  5→
  6→use crate::requirements::probe::EnvironmentProbe;
  7→use crate::requirements::registry::{
  8→    InstallContext, Platform, RequirementCheck, RequirementRegistry,
  9→};
 10→use crate::requirements::status::{GapResult, RequirementStatus};
 11→use crate::steps::resolved::ResolvedStep;
 12→use std::collections::{HashMap, HashSet};
 13→use std::net::TcpStream;
 14→use std::path::{Path, PathBuf};
 15→use std::process::Command;
 16→use std::time::Duration;
 17→
 18→/// Checks whether requirements are satisfied on the system.
 19→///
 20→/// Caches results per-run so the same requirement checked multiple times
 21→/// only executes commands once.
 22→pub struct GapChecker<'a> {
 23→    registry: &'a RequirementRegistry,
 24→    probe: &'a EnvironmentProbe,
 25→    project_root: PathBuf,
 26→    pub(crate) cache: HashMap<String, RequirementStatus>,
 27→}
 28→
 29→impl<'a> GapChecker<'a> {
 30→    /// Create a new gap checker.
 31→    pub fn new(
 32→        registry: &'a RequirementRegistry,
 33→        probe: &'a EnvironmentProbe,
 34→        project_root: &Path,
 35→    ) -> Self {
 36→        Self {
 37→            registry,
 38→            probe,
 39→            project_root: project_root.to_path_buf(),
 40→            cache: HashMap::new(),
 41→        }
 42→    }
 43→
 44→    /// Check all requirements for a step, returning only non-satisfied gaps.
 45→    ///
 46→    /// `provided_requirements` is authoritative — if the environment says
 47→    /// a requirement is provided, skip the check regardless of what the
 48→    /// step's requires list says. Until environments exist, callers pass `None`.
 49→    pub fn check_step(
 50→        &mut self,
 51→        step: &ResolvedStep,
 52→        provided: Option<&HashSet<String>>,
 53→    ) -> Vec<GapResult> {
 54→        let mut gaps = Vec::new();
 55→        for req_name in &step.requires {
 56→            if let Some(provided_set) = provided {
 57→                if provided_set.contains(req_name) {
 58→                    continue;
 59→                }
 60→            }
 61→
 62→            let status = self.check_one(req_name);
 63→            if !status.is_satisfied() {
 64→                gaps.push(GapResult {
 65→                    requirement: req_name.clone(),
 66→                    status,
 67→                });
 68→            }
 69→        }
 70→        gaps
 71→    }
 72→
 73→    /// Check a single requirement, using cache when available.
 74→    pub fn check_one(&mut self, requirement: &str) -> RequirementStatus {
 75→        if let Some(cached) = self.cache.get(requirement) {
 76→            return cached.clone();
 77→        }
 78→
 79→        let status = self.evaluate(requirement);
 80→        self.cache.insert(requirement.to_string(), status.clone());
 81→        status
 82→    }
 83→
 84→    /// Invalidate a cached result for a specific requirement.
 85→    pub fn invalidate(&mut self, requirement: &str) {
 86→        self.cache.remove(requirement);
 87→    }
 88→
 89→    /// Invalidate all cached results.
 90→    pub fn invalidate_all(&mut self) {
 91→        self.cache.clear();
 92→    }
 93→
 94→    /// Resolve the install dependency chain for a requirement.
 95→    ///
 96→    /// Returns the ordered list of requirements that need to be installed,
 97→    /// with dependencies before dependents. Max depth 5, detects circular deps.
 98→    pub fn resolve_install_deps(&self, requirement: &str) -> Result<Vec<String>, String> {
 99→        let mut chain = Vec::new();
100→        let mut visited = HashSet::new();
101→        self.resolve_deps_recursive(requirement, &mut chain, &mut visited, 0)?;
102→        Ok(chain)
103→    }
104→
105→    fn resolve_deps_recursive(
106→        &self,
107→        requirement: &str,
108→        chain: &mut Vec<String>,
109→        visited: &mut HashSet<String>,
110→        depth: usize,
111→    ) -> Result<(), String> {
112→        const MAX_DEPTH: usize = 5;
113→
114→        if depth > MAX_DEPTH {
115→            return Err(format!(
116→                "Requirement dependency chain exceeds max depth of {} for '{}'",
117→                MAX_DEPTH, requirement
118→            ));
119→        }
120→
121→        if visited.contains(requirement) {
122→            return Err(format!(
123→                "Circular dependency detected: '{}' appears twice in the chain",
124→                requirement
125→            ));
126→        }
127→
128→        let Some(req) = self.registry.get(requirement) else {
129→            // Unknown requirement — add it to chain, let caller handle
130→            if !chain.contains(&requirement.to_string()) {
131→                chain.push(requirement.to_string());
132→            }
133→            return Ok(());
134→        };
135→
136→        visited.insert(requirement.to_string());
137→
138→        // Resolve static dependencies
139→        for dep in &req.depends_on {
140→            self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
141→        }
142→
143→        // Resolve dynamic dependencies
144→        if let Some(install_requires_fn) = req.install_requires {
145→            let ctx = self.build_install_context();
146→            let dynamic_deps = install_requires_fn(&ctx);
147→            for dep in &dynamic_deps {
148→                if !visited.contains(dep) {
149→                    self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
150→                }

150→                }
151→            }
152→        }
153→
154→        // Add this requirement after its dependencies
155→        if !chain.contains(&requirement.to_string()) {
156→            chain.push(requirement.to_string());
157→        }
158→
159→        visited.remove(requirement);
160→        Ok(())
161→    }
162→
163→    fn build_install_context(&self) -> InstallContext {
164→        let detected_managers = self
165→            .probe
166→            .inactive_managers()
167→            .iter()
168→            .map(|m| m.name.clone())
169→            .collect::<Vec<_>>();
170→        InstallContext {
171→            detected_managers,
172→            platform: Platform::current(),
173→        }
174→    }
175→
176→    /// Check whether the network is reachable.
177→    ///
178→    /// Attempts a TCP connection to a well-known host with a 2-second timeout.
179→    /// Returns `true` if the connection succeeds, `false` otherwise.
180→    pub fn check_network(&self) -> bool {
181→        // Try multiple well-known hosts to reduce false negatives
182→        const TARGETS: &[(&str, u16)] = &[
183→            ("1.1.1.1", 443), // Cloudflare DNS
184→            ("8.8.8.8", 443), // Google DNS
185→            ("9.9.9.9", 443), // Quad9 DNS
186→        ];
187→        let timeout = Duration::from_secs(2);
188→
189→        for &(host, port) in TARGETS {
190→            let addr = format!("{}:{}", host, port);
191→            if let Ok(addr) = addr.parse() {
192→                if TcpStream::connect_timeout(&addr, timeout).is_ok() {
193→                    return true;
194→                }
195→            }
196→        }
197→        false
198→    }
199→
200→    fn evaluate(&self, requirement: &str) -> RequirementStatus {
201→        let Some(req) = self.registry.get(requirement) else {
202→            return RequirementStatus::Unknown;
203→        };
204→
205→        for check in &req.checks {
206→            if let Some(status) = self.evaluate_check(check, req) {
207→                return status;
208→            }
209→        }
210→
211→        // No check matched — Missing
212→        RequirementStatus::Missing {
213→            install_template: req.install_template.clone(),
214→            install_hint: req.install_hint.clone(),
215→        }
216→    }
217→
218→    fn evaluate_check(
219→        &self,
220→        check: &RequirementCheck,
221→        req: &crate::requirements::registry::Requirement,
222→    ) -> Option<RequirementStatus> {
223→        match check {
224→            RequirementCheck::CommandSucceeds(cmd) => {
225→                if self.run_command_succeeds(cmd) {
226→                    Some(RequirementStatus::Satisfied)
227→                } else {
228→                    None
229→                }
230→            }
231→            RequirementCheck::FileExists(path) => {
232→                let full_path = if Path::new(path).is_absolute() {
233→                    PathBuf::from(path)
234→                } else {
235→                    self.project_root.join(path)
236→                };
237→                if full_path.exists() {
238→                    Some(RequirementStatus::Satisfied)
239→                } else {
240→                    None
241→                }
242→            }
243→            RequirementCheck::ServiceReachable(cmd) => {
244→                if self.run_command_succeeds(cmd) {
245→                    Some(RequirementStatus::Satisfied)
246→                } else {
247→                    // Service check is the main/only check — return ServiceDown
248→                    Some(RequirementStatus::ServiceDown {
249→                        binary_present: self.check_binary_present(cmd),
250→                        install_template: req.install_template.clone(),
251→                        start_command: None,
252→                        start_hint: req
253→                            .install_hint
254→                            .clone()
255→                            .unwrap_or_else(|| format!("Start the {} service", req.name)),
256→                    })
257→                }
258→            }
259→            RequirementCheck::ManagedCommand {
260→                command: tool,
261→                managed_path_patterns,
262→                system_path_patterns,
263→                version_file,
264→            } => self.evaluate_managed_command(
265→                tool,
266→                managed_path_patterns,
267→                system_path_patterns,
268→                version_file.as_deref(),
269→                req,
270→            ),
271→            RequirementCheck::Any(sub_checks) => {
272→                for sub in sub_checks {
273→                    if let Some(status) = self.evaluate_check(sub, req) {
274→                        if status.is_satisfied() || status.can_proceed() {
275→                            return Some(status);
276→                        }
277→                    }
278→                }
279→                None
280→            }
281→        }
282→    }
283→
284→    fn evaluate_managed_command(
285→        &self,
286→        tool: &str,
287→        managed_path_patterns: &[String],
288→        system_path_patterns: &[String],
289→        version_file: Option<&str>,
290→        req: &crate::requirements::registry::Requirement,
291→    ) -> Option<RequirementStatus> {
292→        let full_path = self.probe.full_path();
293→
294→        // Resolve where the tool is on the full (augmented) PATH
295→        if let Some(resolved) =
296→            crate::requirements::probe::resolve_tool_path(tool, full_path.as_slice())
297→        {
298→            let path_str = resolved.to_string_lossy().to_string();
299→
300→            // Check 1: Managed path patterns -> Satisfied
301→            for pattern in managed_path_patterns {
302→                if path_str.contains(pattern) {
303→                    return Some(RequirementStatus::Satisfied);
304→                }
305→            }
306→
307→            // Check 2: Inactive manager with version file
308→            if let Some(vf) = version_file {
309→                if self.project_root.join(vf).exists()
310→                    || self.project_root.join(".tool-versions").exists()
311→                {
312→                    // Check if the tool was found via augmented path (not original PATH)
313→                    let original_path = crate::requirements::probe::parse_system_path();
314→                    let on_original =
315→                        crate::requirements::probe::resolve_tool_path(tool, &original_path);
316→                    if on_original.is_none() {
317→                        // Tool is only on augmented path — it's from an inactive manager
318→                        for mgr in self.probe.inactive_managers() {
319→                            let mgr_binary = format!("{}/", mgr.name);
320→                            if path_str.contains(&mgr_binary)
321→                                || resolved.starts_with(&mgr.install_path)
322→                            {
323→                                return Some(RequirementStatus::Inactive {
324→                                    manager: mgr.name.clone(),
325→                                    binary_path: resolved,
326→                                    activation_hint: mgr.activation.clone(),
327→                                });
328→                            }
329→                        }
330→                    }
331→                }
332→            }
333→
334→            // Check 3: System path patterns -> SystemOnly
335→            for pattern in system_path_patterns {
336→                if path_str.contains(pattern) || path_str.starts_with(pattern) {
337→                    return Some(RequirementStatus::SystemOnly {
338→                        path: resolved,
339→                        install_template: req.install_template.clone(),
340→                        warning: format!(
341→                            "System {} detected at {}. Consider using a version manager.",
342→                            tool, path_str
343→                        ),
344→                    });
345→                }
346→            }
347→
348→            // Check 4: Found on PATH, none of the above -> Satisfied
349→            return Some(RequirementStatus::Satisfied);

 1→//! Bivvy - Interactive development environment setup automation.
 2→//!
 3→//! Bivvy is a CLI tool that replaces ad-hoc `bin/setup` scripts with
 4→//! declarative YAML configuration and a polished interactive CLI experience.
 5→//!
 6→//! # Modules
 7→//!
 8→//! - [`cli`] - Command-line interface and argument parsing
 9→//! - [`config`] - Configuration loading, parsing, and validation
10→//! - [`environment`] - Environment detection and resolution
11→//! - [`error`] - Error types and result aliases
12→//! - [`lint`] - Configuration validation and linting
13→//! - [`registry`] - Template registry and resolution
14→//! - [`runner`] - Step execution orchestration and dependency management
15→//! - [`shell`] - Shell command execution
16→//! - [`state`] - State management for execution history and preferences
17→//! - [`secrets`] - Secret detection and output masking
18→//! - [`steps`] - Step resolution and execution
19→//! - [`ui`] - Interactive prompts, spinners, and terminal output
20→//!
21→//! # Example
22→//!
23→//! ```
24→//! use bivvy::config::{InterpolationContext, resolve_string};
25→//!
26→//! // Resolve variables in a command
27→//! let mut ctx = InterpolationContext::new();
28→//! ctx.prompts.insert("mode".to_string(), "development".to_string());
29→//! let command = resolve_string("rails s -e ${mode}", &ctx).unwrap();
30→//! assert_eq!(command, "rails s -e development");
31→//! ```
32→//!
33→//! For file-based config loading, see the integration tests.
