  1→//! Git template fetching.
  2→//!
  3→//! Provides functionality for cloning and updating git repositories
  4→//! to fetch templates, with support for specific refs and update detection.
  5→
  6→use anyhow::{bail, Result};
  7→use sha2::{Digest, Sha256};
  8→use std::path::{Path, PathBuf};
  9→
 10→/// Fetches templates from git repositories.
 11→pub struct GitFetcher {
 12→    /// Directory for cloned repositories.
 13→    clone_dir: PathBuf,
 14→}
 15→
 16→/// Information about a git fetch.
 17→#[derive(Debug)]
 18→pub struct GitFetchResult {
 19→    /// Path to the fetched content.
 20→    pub local_path: PathBuf,
 21→    /// Current commit SHA.
 22→    pub commit_sha: String,
 23→}
 24→
 25→impl GitFetcher {
 26→    /// Create a new git fetcher.
 27→    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
 28→        Self {
 29→            clone_dir: clone_dir.into(),
 30→        }
 31→    }
 32→
 33→    /// Get the clone directory.
 34→    pub fn clone_dir(&self) -> &PathBuf {
 35→        &self.clone_dir
 36→    }
 37→
 38→    /// Clone or update a repository.
 39→    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
 40→        let repo_path = self.repo_path(url);
 41→
 42→        if repo_path.exists() {
 43→            self.update_repo(&repo_path, git_ref)?;
 44→        } else {
 45→            self.clone_repo(url, &repo_path, git_ref)?;
 46→        }
 47→
 48→        let commit_sha = self.get_head_sha(&repo_path)?;
 49→
 50→        Ok(GitFetchResult {
 51→            local_path: repo_path,
 52→            commit_sha,
 53→        })
 54→    }
 55→
 56→    /// Check if a repository has new commits.
 57→    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
 58→        let remote_sha = self.resolve_ref(url, git_ref)?;
 59→        Ok(remote_sha != current_sha)
 60→    }
 61→
 62→    /// Get the current commit SHA for a ref using ls-remote.
 63→    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
 64→        let refspec = git_ref.unwrap_or("HEAD");
 65→
 66→        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
 67→        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
 68→        let candidates = if refspec == "HEAD" {
 69→            vec![refspec.to_string()]
 70→        } else {
 71→            vec![
 72→                refspec.to_string(),
 73→                format!("refs/heads/{refspec}"),
 74→                format!("refs/tags/{refspec}"),
 75→            ]
 76→        };
 77→
 78→        for candidate in &candidates {
 79→            let output = std::process::Command::new("git")
 80→                .args(["ls-remote", url, candidate])
 81→                .output()?;
 82→
 83→            if !output.status.success() {
 84→                bail!(
 85→                    "Failed to query remote: {}",
 86→                    String::from_utf8_lossy(&output.stderr)
 87→                );
 88→            }
 89→
 90→            let stdout = String::from_utf8_lossy(&output.stdout);
 91→            if let Some(sha) = stdout
 92→                .lines()
 93→                .next()
 94→                .and_then(|line| line.split_whitespace().next())
 95→            {
 96→                return Ok(sha.to_string());
 97→            }
 98→        }
 99→
100→        bail!("Could not resolve ref '{refspec}' from {url}")
101→    }
102→
103→    fn clone_repo(&self, url: &str, path: &Path, git_ref: Option<&str>) -> Result<()> {
104→        if let Some(parent) = path.parent() {
105→            std::fs::create_dir_all(parent)?;
106→        }
107→
108→        let mut cmd = std::process::Command::new("git");
109→        cmd.args(["clone", "--depth", "1"]);
110→
111→        if let Some(r) = git_ref {
112→            cmd.args(["--branch", r]);
113→        }
114→
115→        cmd.args([url, &path.to_string_lossy()]);
116→
117→        let output = cmd.output()?;
118→        if !output.status.success() {
119→            bail!(
120→                "Git clone failed: {}",
121→                String::from_utf8_lossy(&output.stderr)
122→            );
123→        }
124→
125→        Ok(())
126→    }
127→
128→    fn update_repo(&self, path: &PathBuf, git_ref: Option<&str>) -> Result<()> {
129→        let output = std::process::Command::new("git")
130→            .args(["fetch", "origin"])
131→            .current_dir(path)
132→            .output()?;
133→
134→        if !output.status.success() {
135→            bail!(
136→                "Git fetch failed: {}",
137→                String::from_utf8_lossy(&output.stderr)
138→            );
139→        }
140→
141→        let refspec = if let Some(r) = git_ref {
142→            format!("origin/{}", r)
143→        } else {
144→            "origin/HEAD".to_string()
145→        };
146→
147→        let output = std::process::Command::new("git")
148→            .args(["reset", "--hard", &refspec])
149→            .current_dir(path)
150→            .output()?;

  1→//! HTTP template fetching.
  2→//!
  3→//! Provides an HTTP client for fetching templates from URLs with
  4→//! support for ETag-based conditional requests.
  5→
  6→use anyhow::{bail, Result};
  7→use reqwest::blocking::Client;
  8→use std::time::Duration;
  9→
 10→/// Default maximum response body size (10 MB).
 11→const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
 12→
 13→/// Fetches templates over HTTP/HTTPS.
 14→pub struct HttpFetcher {
 15→    client: Client,
 16→    timeout: Duration,
 17→    max_response_size: u64,
 18→}
 19→
 20→/// Response from fetching a template.
 21→#[derive(Debug)]
 22→pub struct FetchResponse {
 23→    /// The template content.
 24→    pub content: String,
 25→    /// ETag header if present.
 26→    pub etag: Option<String>,
 27→    /// Last-Modified header if present.
 28→    pub last_modified: Option<String>,
 29→}
 30→
 31→impl HttpFetcher {
 32→    /// Create a new HTTP fetcher with default 30-second timeout.
 33→    pub fn new() -> Self {
 34→        Self::with_timeout(Duration::from_secs(30))
 35→    }
 36→
 37→    /// Create a new HTTP fetcher with custom timeout.
 38→    pub fn with_timeout(timeout: Duration) -> Self {
 39→        Self {
 40→            client: Client::builder()
 41→                .user_agent("bivvy")
 42→                .timeout(timeout)
 43→                .build()
 44→                .expect("Failed to build HTTP client"),
 45→            timeout,
 46→            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
 47→        }
 48→    }
 49→
 50→    /// Create a new HTTP fetcher with custom timeout and max response size.
 51→    #[cfg(test)]
 52→    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
 53→        Self {
 54→            client: Client::builder()
 55→                .user_agent("bivvy")
 56→                .timeout(timeout)
 57→                .build()
 58→                .expect("Failed to build HTTP client"),
 59→            timeout,
 60→            max_response_size,
 61→        }
 62→    }
 63→
 64→    /// Get the configured timeout.
 65→    pub fn timeout(&self) -> Duration {
 66→        self.timeout
 67→    }
 68→
 69→    /// Fetch a template from a URL.
 70→    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
 71→        let response = self.client.get(url).send()?;
 72→
 73→        if !response.status().is_success() {
 74→            bail!("HTTP {} fetching {}", response.status(), url);
 75→        }
 76→
 77→        // Check Content-Length if available
 78→        if let Some(len) = response.content_length() {
 79→            if len > self.max_response_size {
 80→                bail!(
 81→                    "Response too large ({} bytes, max {} bytes) from {}",
 82→                    len,
 83→                    self.max_response_size,
 84→                    url
 85→                );
 86→            }
 87→        }
 88→
 89→        let etag = response
 90→            .headers()
 91→            .get("etag")
 92→            .and_then(|v| v.to_str().ok())
 93→            .map(String::from);
 94→
 95→        let last_modified = response
 96→            .headers()
 97→            .get("last-modified")
 98→            .and_then(|v| v.to_str().ok())
 99→            .map(String::from);
100→
101→        let content = response.text()?;
102→
103→        // Also check actual content size (in case Content-Length was missing/wrong)
104→        if content.len() as u64 > self.max_response_size {
105→            bail!(
106→                "Response too large ({} bytes, max {} bytes) from {}",
107→                content.len(),
108→                self.max_response_size,
109→                url
110→            );
111→        }
112→
113→        Ok(FetchResponse {
114→            content,
115→            etag,
116→            last_modified,
117→        })
118→    }
119→
120→    /// Fetch with conditional request (If-None-Match).

  1→//! Session storage.
  2→
  3→use std::fs;
  4→use std::path::PathBuf;
  5→
  6→use anyhow::{Context, Result};
  7→
  8→use super::{SessionId, SessionMetadata};
  9→
 10→/// A complete session record.
 11→#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
 12→pub struct Session {
 13→    /// Unique session identifier.
 14→    pub id: SessionId,
 15→    /// Session metadata.
 16→    pub metadata: SessionMetadata,
 17→}
 18→
 19→/// Storage for sessions.
 20→pub struct SessionStore {
 21→    path: PathBuf,
 22→}
 23→
 24→impl SessionStore {
 25→    /// Create a new session store.
 26→    pub fn new(path: impl Into<PathBuf>) -> Self {
 27→        Self { path: path.into() }
 28→    }
 29→
 30→    /// Ensure the store directory exists.
 31→    fn ensure_dir(&self) -> Result<()> {
 32→        fs::create_dir_all(&self.path)
 33→            .with_context(|| format!("Failed to create session store at {:?}", self.path))
 34→    }
 35→
 36→    /// Get the path for a session file.
 37→    fn session_path(&self, id: &SessionId) -> PathBuf {
 38→        self.path.join(format!("{}.json", id))
 39→    }
 40→
 41→    /// Save a session.
 42→    pub fn save(&self, session: &Session) -> Result<()> {
 43→        self.ensure_dir()?;
 44→        let path = self.session_path(&session.id);
 45→        let json = serde_json::to_string_pretty(session)?;
 46→        fs::write(&path, json).with_context(|| format!("Failed to write session to {:?}", path))
 47→    }
 48→
 49→    /// Load a session by ID.
 50→    pub fn load(&self, id: &SessionId) -> Result<Session> {
 51→        let path = self.session_path(id);
 52→        let json =
 53→            fs::read_to_string(&path).with_context(|| format!("Session not found: {:?}", path))?;
 54→        serde_json::from_str(&json).context("Failed to parse session")
 55→    }
 56→
 57→    /// Get the most recent session.
 58→    pub fn get_latest(&self) -> Result<Option<Session>> {
 59→        let sessions = self.list_recent(1)?;
 60→        Ok(sessions.into_iter().next())
 61→    }
 62→
 63→    /// List recent sessions.
 64→    pub fn list_recent(&self, limit: usize) -> Result<Vec<Session>> {
 65→        self.ensure_dir()?;
 66→
 67→        let mut sessions = Vec::new();
 68→        for entry in fs::read_dir(&self.path)? {
 69→            let entry = entry?;
 70→            let path = entry.path();
 71→            if path.extension().is_some_and(|e| e == "json") {
 72→                if let Ok(json) = fs::read_to_string(&path) {
 73→                    if let Ok(session) = serde_json::from_str::<Session>(&json) {
 74→                        sessions.push(session);
 75→                    }
 76→                }
 77→            }
 78→        }
 79→
 80→        // Sort by timestamp descending
 81→        sessions.sort_by(|a, b| b.id.timestamp().cmp(&a.id.timestamp()));
 82→        sessions.truncate(limit);
 83→
 84→        Ok(sessions)
 85→    }
 86→
 87→    /// Clean up old sessions (keep last N).
 88→    pub fn cleanup(&self, keep: usize) -> Result<usize> {
 89→        let sessions = self.list_recent(usize::MAX)?;
 90→        let mut removed = 0;
 91→
 92→        for session in sessions.into_iter().skip(keep) {
 93→            let path = self.session_path(&session.id);
 94→            if fs::remove_file(&path).is_ok() {
 95→                removed += 1;
 96→            }
 97→        }
 98→
 99→        Ok(removed)
100→    }

  1→//! Cache storage implementation.
  2→
  3→use anyhow::{Context, Result};
  4→use sha2::{Digest, Sha256};
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→
  8→use super::entry::CacheEntry;
  9→
 10→/// Storage for cached templates.
 11→pub struct CacheStore {
 12→    /// Root directory for cache.
 13→    root: PathBuf,
 14→}
 15→
 16→impl CacheStore {
 17→    /// Create a new cache store.
 18→    pub fn new(root: impl Into<PathBuf>) -> Self {
 19→        Self { root: root.into() }
 20→    }
 21→
 22→    /// Get the cache root directory.
 23→    pub fn root(&self) -> &Path {
 24→        &self.root
 25→    }
 26→
 27→    /// Ensure the cache directory exists.
 28→    fn ensure_dir(&self) -> Result<()> {
 29→        fs::create_dir_all(&self.root)
 30→            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
 31→    }
 32→
 33→    /// Get the path for storing an entry's content.
 34→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 35→        let key = format!("{}:{}", source_id, template_name);
 36→        let hash = Sha256::digest(key.as_bytes());
 37→        let hash_str = hex::encode(&hash[..16]);
 38→        self.root.join(hash_str)
 39→    }
 40→
 41→    /// Get the metadata file path for an entry.
 42→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 43→        self.content_path(source_id, template_name)
 44→            .with_extension("meta.json")
 45→    }
 46→
 47→    /// Store content and return a cache entry.
 48→    pub fn store(
 49→        &self,
 50→        source_id: &str,
 51→        template_name: &str,
 52→        content: &str,
 53→        ttl_seconds: u64,
 54→    ) -> Result<CacheEntry> {
 55→        self.ensure_dir()?;
 56→
 57→        let content_path = self.content_path(source_id, template_name);
 58→        fs::write(&content_path, content)?;
 59→
 60→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 61→            .with_size(content.len() as u64);
 62→
 63→        self.save_metadata(&entry)?;
 64→
 65→        Ok(entry)
 66→    }
 67→
 68→    /// Load a cached entry's metadata.
 69→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 70→        let meta_path = self.metadata_path(source_id, template_name);
 71→
 72→        if !meta_path.exists() {
 73→            return Ok(None);
 74→        }
 75→
 76→        let json = fs::read_to_string(&meta_path)?;
 77→        let entry: CacheEntry = serde_json::from_str(&json)?;
 78→
 79→        Ok(Some(entry))
 80→    }
 81→
 82→    /// Read the cached content.
 83→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
 84→        fs::read_to_string(&entry.content_path).with_context(|| {
 85→            format!(
 86→                "Failed to read cached content from {:?}",
 87→                entry.content_path
 88→            )
 89→        })
 90→    }
 91→
 92→    /// Save entry metadata.
 93→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
 94→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
 95→        let json = serde_json::to_string_pretty(entry)?;
 96→        fs::write(&meta_path, json)?;
 97→        Ok(())
 98→    }
 99→
100→    /// Update an entry's metadata (e.g., after revalidation).
101→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
102→        self.save_metadata(entry)
103→    }
104→
105→    /// Remove a cached entry.
106→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
107→        let content_path = self.content_path(source_id, template_name);
108→        let meta_path = self.metadata_path(source_id, template_name);
109→
110→        let mut removed = false;
111→
112→        if content_path.exists() {
113→            fs::remove_file(&content_path)?;
114→            removed = true;
115→        }
116→
117→        if meta_path.exists() {
118→            fs::remove_file(&meta_path)?;
119→            removed = true;
120→        }
121→
122→        Ok(removed)
123→    }
124→
125→    /// List all cached entries.
126→    pub fn list(&self) -> Result<Vec<CacheEntry>> {
127→        self.ensure_dir()?;
128→
129→        let mut entries = Vec::new();
130→
131→        for entry in fs::read_dir(&self.root)? {
132→            let entry = entry?;
133→            let path = entry.path();
134→
135→            if path.extension().is_some_and(|e| e == "json") {
136→                if let Ok(json) = fs::read_to_string(&path) {
137→                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
138→                        entries.push(cache_entry);
139→                    }
140→                }
141→            }
142→        }
143→
144→        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
145→        Ok(entries)
146→    }
147→
148→    /// Clear all cached entries.
149→    pub fn clear(&self) -> Result<usize> {
150→        let entries = self.list()?;
151→        let count = entries.len();
152→
153→        for entry in entries {
154→            let _ = self.remove(&entry.source_id, &entry.template_name);
155→        }
156→
157→        Ok(count)
158→    }
159→
160→    /// Get total cache size in bytes.
161→    pub fn total_size(&self) -> Result<u64> {
162→        let entries = self.list()?;
163→        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
164→    }
165→}
